import type { Medicine } from "@/lib/types";

/** Prescribing defaults applied when a medicine is picked in the Rx builder. */
export type DrugPrescribingDefaults = {
  dosage?: string;
  route?: string;
  frequency?: string;
  duration?: string;
  quantity?: string;
  instructions?: string;
};

export type DrugSuggestion = {
  id: string;
  name: string;
  source: "common" | "clinic";
  usageCount: number;
  stockQuantity?: number;
  reorderLevel?: number;
  genericName?: string | null;
  category?: string | null;
  strength?: string | null;
  batchNumber?: string | null;
  expiryDate?: Date | string | null;
  unitPrice?: number | null;
  defaults: DrugPrescribingDefaults;
};

export type ClinicDrugEntry = {
  id: string;
  name: string;
  normalizedName: string;
  usageCount: number;
  stockQuantity?: number;
  reorderLevel?: number;
  genericName?: string | null;
  category?: string | null;
  strength?: string | null;
  batchNumber?: string | null;
  expiryDate?: Date | string | null;
  unitPrice?: number | null;
  dosage?: string | null;
  route?: string | null;
  frequency?: string | null;
  duration?: string | null;
  quantity?: string | null;
  instructions?: string | null;
};

export type CommonDrug = {
  name: string;
  genericName?: string;
  category?: string;
  strength?: string;
  form?: string;
  therapeuticClass?: string;
} & DrugPrescribingDefaults;

/* Helper constructors */
function oral(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Tablet", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1 tablet",
    route: "Oral",
    frequency: "Twice daily",
    duration: "5 Days",
    instructions: "After meals",
    ...defaults,
  };
}

function capsule(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Capsule", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1 capsule",
    route: "Oral",
    frequency: "Twice daily",
    duration: "5 Days",
    instructions: "After meals",
    ...defaults,
  };
}

function syrup(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Syrup", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "5 ml",
    route: "Oral",
    frequency: "Three times daily",
    duration: "5 Days",
    instructions: "After meals",
    ...defaults,
  };
}

function topical(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Gel / Ointment", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "Apply thinly",
    route: "Topical",
    frequency: "Twice daily",
    duration: "7 Days",
    instructions: "Apply gently to affected area",
    ...defaults,
  };
}

function inhaler(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Inhaler", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "2 puffs",
    route: "Inhalation",
    frequency: "Twice daily",
    duration: "Until review",
    instructions: "Rinse mouth thoroughly after use",
    ...defaults,
  };
}

function drops(
  name: string,
  route: "Ophthalmic" | "Otic" | "Nasal",
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Drops", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1-2 drops",
    route,
    frequency: "Three times daily",
    duration: "5 Days",
    instructions: route === "Ophthalmic" ? "Instill into affected eye" : route === "Otic" ? "Instill into affected ear canal" : "Instill into nostrils",
    ...defaults,
  };
}

function inj(
  name: string,
  route: "Intramuscular" | "Intravenous" | "Subcutaneous",
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Injection", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1 ampoule / vial",
    route,
    frequency: "Stat (Single dose)",
    duration: "1 Day",
    instructions: "Administer under nursing supervision",
    ...defaults,
  };
}

function ivFluid(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "IV Fluid", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: "IV Infusion",
    therapeuticClass,
    dosage: "500 ml",
    route: "Intravenous",
    frequency: "Once daily / As needed",
    duration: "1 Day",
    instructions: "Slow IV infusion at 30-40 drops/min",
    ...defaults,
  };
}

function sachet(
  name: string,
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Sachet", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1 sachet",
    route: "Oral",
    frequency: "Once daily",
    duration: "30 Days",
    instructions: "Dissolve completely in a glass of clean water or milk",
    ...defaults,
  };
}

function suppository(
  name: string,
  route: "Rectal" | "Vaginal",
  overrides: DrugPrescribingDefaults & {
    genericName?: string;
    category?: string;
    strength?: string;
    therapeuticClass?: string;
  } = {}
): CommonDrug {
  const { genericName, category = "Suppository", strength, therapeuticClass, ...defaults } = overrides;
  return {
    name,
    genericName,
    category,
    strength,
    form: category,
    therapeuticClass,
    dosage: "1 unit",
    route,
    frequency: "At bedtime",
    duration: "3 Days",
    instructions: "Insert deeply at bedtime",
    ...defaults,
  };
}

